initJs:
function(container, apiUrl, tables) {
  const tbody = container.querySelector("#inventory-tbody");
  const resultCount = container.querySelector("#result-count");
  const noResults = container.querySelector("#no-results");
  const errorMessage = container.querySelector("#error-message");

  // 店舗データを取得してプルダウンに設定
  async function loadStores() {
    const storeSelect = container.querySelector("#store-select");
    const stores = await window.aivicApi.list(1); // 店舗マスタのインデックス
    if (stores) {
      stores.forEach(store => {
        const option = document.createElement("option");
        option.value = store.id;
        option.textContent = `${store.店舗コード || ''} - ${store.店舗名 || ''}`;
        storeSelect.appendChild(option);
      });
    }
  }

  // エラーメッセージ表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove("hidden");
    setTimeout(() => {
      errorMessage.classList.add("hidden");
    }, 5000);
  }

  // 在庫状況を判定
  function getStockStatus(currentStock, safetyStock) {
    if (!safetyStock || safetyStock === 0) return "適正";
    if (currentStock === 0) return "不足";
    if (currentStock < safetyStock) return "不足";
    if (currentStock > safetyStock * 2) return "過剰";
    return "適正";
  }

  // 在庫一覧を描画
  function renderInventory(inventoryData) {
    if (!inventoryData || inventoryData.length === 0) {
      tbody.innerHTML = "";
      resultCount.textContent = "検索結果: 0件";
      noResults.classList.remove("hidden");
      return;
    }

    noResults.classList.add("hidden");
    resultCount.textContent = `検索結果: ${inventoryData.length}件`;

    tbody.innerHTML = inventoryData.map(item => {
      const currentStock = item.現在在庫数 || 0;
      const safetyStock = item.安全在庫数 || 0;
      const status = getStockStatus(currentStock, safetyStock);
      const statusColor = status === "不足" ? "#ff6b6b" : status === "過剰" ? "#ffa726" : "#4caf50";

      return `
        <tr data-id="${item.id || ''}">
          <td>${item.商品コード || ''}</td>
          <td>${item.商品名 || ''}</td>
          <td style="text-align: right;">${currentStock.toLocaleString()}</td>
          <td style="text-align: right;">${safetyStock.toLocaleString()}</td>
          <td>
            <span style="display: inline-block; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500; color: white; background: ${statusColor};">
              ${status}
            </span>
          </td>
          <td>${item.最終入荷日 ? new Date(item.最終入荷日).toLocaleDateString('ja-JP') : '-'}</td>
        </tr>
      `;
    }).join("");
  }

  // 検索処理
  async function performSearch() {
    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const productName = container.querySelector("#product-name-search").value.trim();
    const productCode = container.querySelector("#product-code-search").value.trim();
    const stockStatus = container.querySelector("#stock-status-filter").value;

    // 店舗未選択チェック
    if (!storeId) {
      showError("店舗を選択してください");
      return;
    }

    // 入力値検証
    if (productName && (productName.includes('<') || productName.includes('>') || productName.includes('script'))) {
      showError("商品名に不正な文字が含まれています");
      return;
    }

    if (productCode && !/^[A-Za-z0-9\-_]*$/.test(productCode)) {
      showError("商品コードは英数字、ハイフン、アンダースコアのみ使用可能です");
      return;
    }

    if (productName.length > 255) {
      showError("商品名は255文字以内で入力してください");
      return;
    }

    if (productCode.length > 20) {
      showError("商品コードは20桁以内で入力してください");
      return;
    }

    try {
      // 商品マスタを取得
      const products = await window.aivicApi.list(2); // 商品マスタのインデックス
      if (!products) {
        showError("商品データの取得に失敗しました");
        return;
      }

      // フィルタリング処理
      let filteredProducts = products.filter(product => {
        // カテゴリフィルタ
        if (category && product.商品カテゴリ !== category) return false;

        // 商品名検索
        if (productName && !product.商品名?.toLowerCase().includes(productName.toLowerCase())) return false;

        // 商品コード検索
        if (productCode && !product.商品コード?.toLowerCase().includes(productCode.toLowerCase())) return false;

        return true;
      });

      // 在庫情報を追加（実際の実装では在庫テーブルから取得）
      const inventoryData = filteredProducts.map(product => {
        const currentStock = Math.floor(Math.random() * 1000); // サンプルデータ
        const safetyStock = Math.floor(Math.random() * 100) + 50; // サンプルデータ
        const status = getStockStatus(currentStock, safetyStock);

        return {
          ...product,
          現在在庫数: currentStock,
          安全在庫数: safetyStock,
          在庫状況: status,
          最終入荷日: new Date(Date.now() - Math.random() * 30 * 24 * 60 * 60 * 1000) // 過去30日以内のランダム日付
        };
      });

      // 在庫状況フィルタ
      if (stockStatus) {
        filteredProducts = inventoryData.filter(item => item.在庫状況 === stockStatus);
      } else {
        filteredProducts = inventoryData;
      }

      renderInventory(filteredProducts);

    } catch (error) {
      showError("検索処理中にエラーが発生しました");
      console.error("Search error:", error);
    }
  }

  // CSVエクスポート
  async function exportCSV() {
    try {
      const products = await window.aivicApi.list(2);
      if (!products || products.length === 0) {
        showError("エクスポートするデータがありません");
        return;
      }

      const headers = ["商品コード", "商品名", "現在在庫数", "安全在庫数", "在庫状況", "最終入荷日"];
      const csvContent = "\uFEFF" + headers.join(",") + "\n" + 
        products.map(product => {
          const currentStock = Math.floor(Math.random() * 1000);
          const safetyStock = Math.floor(Math.random() * 100) + 50;
          const status = getStockStatus(currentStock, safetyStock);
          const lastReceived = new Date(Date.now() - Math.random() * 30 * 24 * 60 * 60 * 1000).toLocaleDateString('ja-JP');

          return [
            `"${product.商品コード || ''}"`,
            `"${product.商品名 || ''}"`,
            currentStock,
            safetyStock,
            `"${status}"`,
            `"${lastReceived}"`
          ].join(",");
        }).join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `在庫一覧_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();

    } catch (error) {
      showError("CSVエクスポート中にエラーが発生しました");
      console.error("Export error:", error);
    }
  }

  // 検索条件クリア
  function clearSearchConditions() {
    container.querySelector("#store-select").value = "";
    container.querySelector("#category-select").value = "";
    container.querySelector("#product-name-search").value = "";
    container.querySelector("#product-code-search").value = "";
    container.querySelector("#stock-status-filter").value = "";
    tbody.innerHTML = "";
    resultCount.textContent = "検索結果: 0件";
    noResults.classList.add("hidden");
  }

  // イベントリスナー設定
  container.querySelector("#btn-search").addEventListener("click", performSearch);
  container.querySelector("#btn-clear").addEventListener("click", clearSearchConditions);
  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // 初期化処理
  loadStores();

  // 初期表示（全件表示）
  container.querySelector("#btn-search").addEventListener("click", () => {
    if (!container.querySelector("#store-select").value) {
      // 店舗未選択の場合は全件表示
      window.aivicApi.list(2).then(products => {
        if (products) {
          const inventoryData = products.map(product => {
            const currentStock = Math.floor(Math.random() * 1000);
            const safetyStock = Math.floor(Math.random() * 100) + 50;
            return {
              ...product,
              現在在庫数: currentStock,
              安全在庫数: safetyStock,
              在庫状況: getStockStatus(currentStock, safetyStock),
              最終入荷日: new Date(Date.now() - Math.random() * 30 * 24 * 60 * 60 * 1000)
            };
          });
          renderInventory(inventoryData);
        }
      });
    }
  });
}
